				// For CJS / UMD it's more optimal size-wise to export everything as a single object.
				exports = `export default {${sources
					.map((s) => `${s.exportName}: ${s.exportValue}`)
					.join(",")}}`;
			}

			return `
      ${sources
				.map((s) => s.import)
				.filter(Boolean)
				.join("\n")}
      ${exports}
      `;
		},
	};
